(579, 173, '_form', '<div class=\"appointment\">\n\n<div class=\"title\">Book Tour Now</div>\n\n[dynamichidden page-title \"CF7_get_post_var key=\'title\'\"]\n\n  <div class=\"item\">\n    <label>Full Name</label>\n    [text* fullname placeholder \"Enter your full name\"]\n  </div>\n\n  <div class=\"item\">\n    <label>Phone Number</label>\n    [tel* phone placeholder \"Enter your phone number\"]\n  </div>\n\n  <div class=\"item\">\n    <label>Email Address</label>\n    [email email placeholder \"Enter your email address\"]\n  </div>\n\n  <div class=\"item\">\n    <label>Tour Name</label>\n    [text tour-name class:product_name placeholder \"Tour name\"]\n  </div>\n\n  <div class=\"item\">\n    <label>Tour Price</label>\n    [text tour-price class:product_price placeholder \"Tour price\"]\n  </div>\n\n  <div class=\"item\">\n    <label>Message</label>\n    [textarea mess placeholder \"Write your message here\"]\n  </div>\n\n  <div class=\"product_price\"></div>\n\n  <button type=\"submit\" class=\"wpcf7-form-control dark has-spinner wpcf7-submit\">\n    Book Tour\n    <span>\n      <img src=\"http://localhost/vionis/wp-content/uploads/2023/06/right-arrow-blue.png\" alt=\"arrow\">\n    </span>\n  </button>\n\n</div>'),
(580, 173, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:26:\"Đặt tour (Vionis Trvel)\";s:6:\"sender\";s:28:\"<wordpress@vionistravel.com>\";s:9:\"recipient\";s:21:\"maiatech611@gmail.com\";s:4:\"body\";s:3209:\"<div style=\"font-family:Arial,sans-serif;background:#f4f7fb;padding:30px;\">\n\n  <div style=\"max-width:650px;margin:auto;background:#ffffff;border-radius:14px;overflow:hidden;box-shadow:0 4px 20px rgba(0,0,0,.08);\">\n\n<!-- HEADER -->\n<div style=\"background:linear-gradient(135deg,#0ea5e9,#2563eb);padding:30px;text-align:center;color:#fff;\">\n  <h1 style=\"margin:0;font-size:28px;\">🌍 New Tour Booking</h1>\n  <p style=\"margin-top:10px;font-size:14px;opacity:.9;\">\n    A customer has submitted a new booking request\n  </p>\n</div>\n\n<!-- BODY -->\n<div style=\"padding:30px;\">\n\n  <!-- TOUR INFO -->\n  <div style=\"margin-bottom:28px;\">\n    <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #2563eb;padding-left:12px;\">\n      Tour Information\n    </h2>\n\n    <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse;margin-top:15px;\">\n      <tr style=\"background:#f9fafb;\">\n        <td style=\"font-weight:bold;width:180px;\">Tour Name</td>\n        <td>[tour-name]</td>\n      </tr>\n      <tr>\n        <td style=\"font-weight:bold;\">Tour Price</td>\n        <td>[tour-price]</td>\n      </tr>\n    </table>\n  </div>\n\n  <!-- CUSTOMER INFO -->\n  <div style=\"margin-bottom:28px;\">\n    <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #10b981;padding-left:12px;\">\n      Customer Information\n    </h2>\n\n    <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse;margin-top:15px;\">\n      <tr style=\"background:#f9fafb;\">\n        <td style=\"font-weight:bold;width:180px;\">Full Name</td>\n        <td>[fullname]</td>\n      </tr>\n      <tr>\n        <td style=\"font-weight:bold;\">Phone Number</td>\n        <td>[phone]</td>\n      </tr>\n      <tr style=\"background:#f9fafb;\">\n        <td style=\"font-weight:bold;\">Email Address</td>\n        <td>[email]</td>\n      </tr>\n    </table>\n  </div>\n\n  <!-- MESSAGE -->\n  <div style=\"margin-bottom:28px;\">\n    <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #f59e0b;padding-left:12px;\">\n      Customer Message\n    </h2>\n\n    <div style=\"background:#f9fafb;padding:18px;border-radius:10px;margin-top:15px;line-height:1.7;color:#374151;\">\n      [mess]\n    </div>\n  </div>\n\n  <!-- BOOKING DETAILS -->\n  <div style=\"margin-bottom:10px;\">\n    <h2 style=\"font-size:18px;color:#111827;border-left:4px solid #ef4444;padding-left:12px;\">\n      Booking Details\n    </h2>\n\n    <table width=\"100%\" cellpadding=\"10\" cellspacing=\"0\" style=\"border-collapse:collapse;margin-top:15px;\">\n      <tr style=\"background:#f9fafb;\">\n        <td style=\"font-weight:bold;width:180px;\">Submitted Time</td>\n        <td>[_date] [_time]</td>\n      </tr>\n      <tr>\n        <td style=\"font-weight:bold;\">Page Title</td>\n        <td>[page-title]</td>\n      </tr>\n      <tr style=\"background:#f9fafb;\">\n        <td style=\"font-weight:bold;\">Page URL</td>\n        <td>[_url]</td>\n      </tr>\n      <tr>\n        <td style=\"font-weight:bold;\">IP Address</td>\n        <td>[_remote_ip]</td>\n      </tr>\n    </table>\n  </div>\n\n</div>\n\n<!-- FOOTER -->\n<div style=\"background:#111827;padding:22px;text-align:center;color:#d1d5db;font-size:13px;\">\n  ✈️ VIONIS TRAVEL <br>\n  Thank you for using our booking system.\n</div>\n\n  </div>\n\n</div>\";s:18:\"additional_headers\";s:0:\"\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
(581, 173, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:36:\"[_site_title] <quoc890294@gmail.com>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:142:\"Nội dung thông điệp:\n[your-message]\n\n-- \nEmail này được gửi đến từ form liên hệ của website [_site_title] ([_site_url])\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(582, 173, '_messages', 'a:26:{s:12:\"mail_sent_ok\";s:53:\"Xin cảm ơn, form đã được gửi thành công.\";s:12:\"mail_sent_ng\";s:118:\"Có lỗi xảy ra trong quá trình gửi. Xin vui lòng thử lại hoặc liên hệ người quản trị website.\";s:16:\"validation_error\";s:86:\"Có một hoặc nhiều mục nhập có lỗi. Vui lòng kiểm tra và thử lại.\";s:4:\"spam\";s:118:\"Có lỗi xảy ra trong quá trình gửi. Xin vui lòng thử lại hoặc liên hệ người quản trị website.\";s:12:\"accept_terms\";s:67:\"Bạn phải chấp nhận điều khoản trước khi gửi form.\";s:16:\"invalid_required\";s:27:\"Please fill out this field.\";s:16:\"invalid_too_long\";s:32:\"This field has a too long input.\";s:17:\"invalid_too_short\";s:33:\"This field has a too short input.\";s:17:\"dtx_invalid_email\";s:35:\"Please enter a valid email address.\";s:15:\"dtx_invalid_tel\";s:34:\"Please enter a valid phone number.\";s:18:\"dtx_invalid_number\";s:28:\"Please enter a valid number.\";s:16:\"dtx_invalid_date\";s:26:\"Please enter a valid date.\";s:13:\"upload_failed\";s:36:\"Tải file lên không thành công.\";s:24:\"upload_file_type_invalid\";s:69:\"Bạn không được phép tải lên file theo định dạng này.\";s:21:\"upload_file_too_large\";s:31:\"The uploaded file is too large.\";s:23:\"upload_failed_php_error\";s:36:\"Tải file lên không thành công.\";s:12:\"invalid_date\";s:41:\"Please enter a date in YYYY-MM-DD format.\";s:14:\"date_too_early\";s:32:\"This field has a too early date.\";s:13:\"date_too_late\";s:31:\"This field has a too late date.\";s:14:\"invalid_number\";s:22:\"Please enter a number.\";s:16:\"number_too_small\";s:34:\"This field has a too small number.\";s:16:\"number_too_large\";s:34:\"This field has a too large number.\";s:23:\"quiz_answer_not_correct\";s:30:\"Câu trả lời chưa đúng.\";s:13:\"invalid_email\";s:30:\"Please enter an email address.\";s:11:\"invalid_url\";s:19:\"Please enter a URL.\";s:11:\"invalid_tel\";s:32:\"Please enter a telephone number.\";}'),
