(5673, 1256, '_google_map', 'field_64990730f97e5'),
(5674, 1256, 'tour_time', '20260530'),
(5675, 1256, '_tour_time', 'field_649bf7010d796'),
(5676, 1256, 'schedule_0_title', '7:15-8:00'),
(5677, 1256, '_schedule_0_title', 'field_6499083f75a8d'),
(5678, 1256, 'schedule_0_content', '<span style=\"font-weight: 400;\">Our tour guide will pick you up from your hotel. We take you to Ninh Binh province which is about 120 km far from Hanoi Old Quarter.</span>'),
(5679, 1256, '_schedule_0_content', 'field_6499084975a8e'),
(5680, 1256, 'schedule', '9'),
(5681, 1256, '_schedule', 'field_6499081575a8c'),
(5682, 1256, 'inline_featured_image', '0'),
(5683, 1256, 'rank_math_internal_links_processed', '1'),
(5684, 1256, 'rank_math_primary_product_cat', '42'),
(5685, 1256, 'rank_math_primary_product_start', '25'),
(5686, 1256, 'rank_math_primary_product_end', '26'),
(5687, 1256, 'rank_math_primary_product_tour', '24'),
(5688, 1256, 'rank_math_primary_tour_time', '49'),
(5689, 1256, 'schedule_1_title', '9h00-9h15'),
(5690, 1256, '_schedule_1_title', 'field_6499083f75a8d'),
(5691, 1256, 'schedule_1_content', '<span style=\"font-weight: 400;\">Have a short break for 20 minutes to relax</span>'),
(5692, 1256, '_schedule_1_content', 'field_6499084975a8e'),
(5693, 1256, 'schedule_2_title', '10h15-10h30'),
(5694, 1256, '_schedule_2_title', 'field_6499083f75a8d'),
(5695, 1256, 'schedule_2_content', '<span style=\"font-weight: 400;\">Arrive</span><b> restaurant</b><span style=\"font-weight: 400;\"> and start cycling 20 minutes to</span> <span style=\"font-weight: 400;\">Hoa Lu ancient capital, then park the bicycle and walk to visit </span><b>Hoa Lu</b><span style=\"font-weight: 400;\">. This is the first capital of Vietnam, you will be impressed by the outstanding architecture when entering temples of King Dinh and King Le, the first and second emperors of ancient Vietnam, built in the 17th century.</span>\r\n\r\n<i><span style=\"font-weight: 400;\">(If you prefer not to cycle, we will transfer you by bus to Hoa Lu, where our tour guide will meet you and guide you to the temples. After the visit, we will transfer you back to Restaurant)</span></i>'),
(5696, 1256, '_schedule_2_content', 'field_6499084975a8e'),
(5697, 1256, 'schedule_3_title', '11h30'),
(5698, 1256, '_schedule_3_title', 'field_6499083f75a8d'),
(5699, 1256, 'schedule_3_content', '<span style=\"font-weight: 400;\">Continue cycling tour 30 minutes more around the village to discover the life of local people and come back to Vietnam restaurant.</span>'),
(5700, 1256, '_schedule_3_content', 'field_6499084975a8e'),
(5701, 1256, 'schedule_4_title', '12h00'),
(5702, 1256, '_schedule_4_title', 'field_6499083f75a8d'),
(5703, 1256, 'schedule_4_content', '<span style=\"font-weight: 400;\">Have Lunch at </span><b> Vietnam Restaurant</b><span style=\"font-weight: 400;\">. You can have a panoramic view of the poetic mountain and river scenery of Ninh Binh while enjoying the delicious foods.</span>\r\n\r\n<span style=\"font-weight: 400;\"> </span><b><i>Lunch will be served in accordance to service you choose:</i></b>\r\n\r\n<i><span style=\"font-weight: 400;\">- </span></i><b>Deluxe Set Menu style: </b><span style=\"font-weight: 400;\">on the </span><b>2nd floor </b><span style=\"font-weight: 400;\">if you choose the </span><b>Luxury D-car</b><span style=\"font-weight: 400;\"> option. </span>\r\n\r\n<span style=\"font-weight: 400;\">Deluxe Set Menu lunch is served in a private and cozy atmosphere. Foods are decorated impressively on the table.</span><b>\r\n</b><span style=\"font-weight: 400;\">- </span><b>Buffet style:</b><span style=\"font-weight: 400;\"> on the </span><b>3rd floor </b><span style=\"font-weight: 400;\">if you choose the </span><b>Thaco Limousine </b><span style=\"font-weight: 400;\">option. </span>\r\n\r\n<span style=\"font-weight: 400;\">Buffet lunch is served in a modern and elegant atmosphere with many local foods.</span>\r\n\r\n<em><span style=\"font-weight: 400;\"><strong>Note:</strong> Vegetarian foods are always available on both Deluxe Set Menu and Buffet.</span></em>'),
(5704, 1256, '_schedule_4_content', 'field_6499084975a8e'),
(5705, 1256, 'schedule_5_title', '13h00 – 13h30'),
(5706, 1256, '_schedule_5_title', 'field_6499083f75a8d'),
(5707, 1256, 'schedule_5_content', '<b>Visit Tam Coc or Trang An </b><span style=\"font-weight: 400;\"> by 1.5- hour on the boat ride. During the boat trip, you will be surprised by the charming beauty here with paddy fields, river, water, cloud, sky and stunning cave system. All make  a masterpiece which Vietnamese people call “Halong Bay on land”.</span>'),
(5708, 1256, '_schedule_5_content', 'field_6499084975a8e'),
(5709, 1256, 'schedule_6_title', '16h00-16:30'),
(5710, 1256, '_schedule_6_title', 'field_6499083f75a8d'),
(5711, 1256, 'schedule_6_content', '<span style=\"font-weight: 400;\">Get on the bus to go to </span><b>Mua Cave ( Dancing Cave)</b><span style=\"font-weight: 400;\">.</span> <span style=\"font-weight: 400;\">Walk up almost 500 steps, you can reach the top of Lying Dragon Mountain, and have an amazing panoramic view of Tam Coc from here.</span>'),
(5712, 1256, '_schedule_6_content', 'field_6499084975a8e'),
(5713, 1256, 'schedule_7_title', '17h00 - 17h30'),
(5714, 1256, '_schedule_7_title', 'field_6499083f75a8d'),
(5715, 1256, 'schedule_7_content', '<span style=\"font-weight: 400;\">Get on the Bus to return to Hanoi</span>'),
(5716, 1256, '_schedule_7_content', 'field_6499084975a8e'),
(5717, 1256, 'schedule_8_title', '19h00 - 19h30'),
(5718, 1256, '_schedule_8_title', 'field_6499083f75a8d'),
(5719, 1256, 'schedule_8_content', '<span style=\"font-weight: 400;\">Arrive in Hanoi and get dropped off at the Hotel. The trip ends !</span>\r\n\r\n<b><i>Note :</i></b><i><span style=\"font-weight: 400;\"> </span></i>\r\n\r\n<i><span style=\"font-weight: 400;\">Programs &amp; schedules are subject to change without prior notice due to the weather conditions or external factors.</span></i>\r\n\r\n<i><span style=\"font-weight: 400;\">On weekend, some roads will not allow vehicles to make room for the walking street, therefore our Luxury D-car / Thaco Limousine/ Shutter Bus will drop you off at the closest and suitable point in the Old Quarter instead.</span></i>'),
(5720, 1256, '_schedule_8_content', 'field_6499084975a8e'),
