(6162, 1155, 'google_map', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d476856.7683751249!2d105.65274004999999!3d20.97485195!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3135ab9bd9861ca1%3A0xe7887f7b72ca17a9!2zSMOgIE7hu5lpLCBWaeG7h3QgTmFt!5e0!3m2!1svi!2s!4v1779941380932!5m2!1svi!2s\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>'),
(6163, 1155, '_google_map', 'field_64990730f97e5'),
(6164, 1155, 'tour_time', '20260529'),
(6165, 1155, '_tour_time', 'field_649bf7010d796'),
(6166, 1155, 'schedule_0_title', '8.00- 8.30'),
(6167, 1155, '_schedule_0_title', 'field_6499083f75a8d'),
(6168, 1155, 'schedule_0_content', '<span style=\"font-weight: 400;\">Get picked up by our friendly guide and start to explore Hanoi City</span>'),
(6169, 1155, '_schedule_0_content', 'field_6499084975a8e'),
(6170, 1155, 'schedule_1_title', '08.45'),
(6171, 1155, '_schedule_1_title', 'field_6499083f75a8d'),
(6172, 1155, 'schedule_1_content', '<span style=\"font-weight: 400;\">Arrive at Tran Quoc Pagoda located on Golden Fish IsLand in West Lake. </span><span style=\"font-weight: 400;\">It is the oldest pagoda in Ha Noi built in the 6th century.</span>'),
(6173, 1155, '_schedule_1_content', 'field_6499084975a8e'),
(6174, 1155, 'schedule_2_title', '09.30'),
(6175, 1155, '_schedule_2_title', 'field_6499083f75a8d'),
(6176, 1155, 'schedule_2_content', '<span style=\"font-weight: 400;\">Visit Ho Chi Minh complex, you have a chance to see the embalmed body of Ho Chi Minh then walk around the garden to see 2 houses where he lived &amp; worked from 1954 to 1969. Then visit One Pillar Pagoda where worships the Godess of Mercy – It is the most unique padoga in the world</span>\r\n<ul>\r\n 	<li><span style=\"font-weight: 400;\">Should dress modestly by covering from shoulders to knees when visiting Ho Chi Minh mausoleum, temples, pagodas…</span></li>\r\n 	<li><span style=\"font-weight: 400;\">Ho Chi Minh’s Mausoleum is closed on Mondays and Fridays.</span></li>\r\n 	<li><span style=\"font-weight: 400;\">Ho Chi Minh’s Mausoleum is closed at least 2 months (15</span><span style=\"font-weight: 400;\">th</span><span style=\"font-weight: 400;\"> June -15</span><span style=\"font-weight: 400;\">th</span><span style=\"font-weight: 400;\"> August) for the annual maintaining but still can take picture Mausoleum and visit around that area</span></li>\r\n</ul>'),
(6177, 1155, '_schedule_2_content', 'field_6499084975a8e'),
(6178, 1155, 'schedule_3_title', '11.15'),
(6179, 1155, '_schedule_3_title', 'field_6499083f75a8d'),
(6180, 1155, 'schedule_3_content', '<span style=\"font-weight: 400;\">Visit Vietnam Ethnology Museum to learn about the culture of 54 ethnic groups living in the whole country of Vietnam</span>\r\n\r\n<span style=\"font-weight: 400;\"><em>Special Note:</em> <em>we will visit Women Museum instead of Ethnology Museum closed on Mondays</em></span>'),
(6181, 1155, '_schedule_3_content', 'field_6499084975a8e'),
(6182, 1155, 'schedule_4_title', '12.45'),
(6183, 1155, '_schedule_4_title', 'field_6499083f75a8d'),
(6184, 1155, 'schedule_4_content', '<span style=\"font-weight: 400;\">Have lunch at our restaurant. You have an opportunity to enjoy Vietnamese cuisine </span><span style=\"font-weight: 400;\">with 8 delicious dishes.</span>'),
(6185, 1155, '_schedule_4_content', 'field_6499084975a8e'),
(6186, 1155, 'schedule_5_title', '14.00-14.15'),
(6187, 1155, '_schedule_5_title', 'field_6499083f75a8d'),
(6188, 1155, 'schedule_5_content', '<span style=\"font-weight: 400;\">Continue to visit Temple of Literature – the first university of Vietnam, established in the 11 centuries</span>'),
(6189, 1155, '_schedule_5_content', 'field_6499084975a8e'),
(6190, 1155, 'schedule_6_title', '15.15'),
(6191, 1155, '_schedule_6_title', 'field_6499083f75a8d'),
(6192, 1155, 'schedule_6_content', '<span style=\"font-weight: 400;\">Leave for Hoa Lo Prison Museum which originally used by the French colonists in Indochina for political prisoners, and later by North Vietnam for U.S. prisoners of war during the Vietnam War. During this later period, it was known to American POWs as the Hanoi Hilton</span>'),
(6193, 1155, '_schedule_6_content', 'field_6499084975a8e'),
(6194, 1155, 'schedule_7_title', '16.15 -16.30'),
(6195, 1155, '_schedule_7_title', 'field_6499083f75a8d'),
(6196, 1155, 'schedule_7_content', '<span style=\"font-weight: 400;\">Tour finishes. Back to hotel</span>'),
(6197, 1155, '_schedule_7_content', 'field_6499084975a8e'),
