(1080, 6, '2025-04-22 23:57:42', '2025-04-22 16:57:42', '.box-text a:not(.button),\n.box-text h4,\n.box-text h5,\n.box-text h6 {\n    line-height: 1.3;\n    color: rgb(211 27 27);\n    margin-bottom: .1em;\n    margin-top: .1em;\n    transition: color 0.3s ease, transform 0.3s ease;\n}\n\n.box-text a:not(.button):hover,\n.box-text h4:hover,\n.box-text h5:hover,\n.box-text h6:hover {\n    color: rgb(255, 0, 0);\n    transform: translateY(-3px);\n    cursor: pointer;\n}\n\n\n\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 22px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n}\n.home_blog .box-blog-post {\n    box-shadow: 0 0 18px rgba(0, 0, 0, 0.05);\n    border-radius: 10px; /* Bo góc */\n    transition: all 0.s ease;\n}\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 5px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n    border: 1px solid rgba(0, 0, 0, 0.05); /* Giữ viền khi hover */\n}\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.tour-outbound .tour-outbound__title h2 {\n    color: #fff;\n       font-size: 3.5rem;\n    font-style: normal;\n    font-weight: 700;\n    line-height: normal;\n    text-transform: uppercase;\n}\n\n.home-introduce .home-introduce__title h1 {\n    margin-bottom: 1.06rem;\n}\n\n.phongvt-title-main h2, .phongvt-title-main h1, .phongvt-title-main h3, .phongvt-title-main-p p {\n    object-position: 50% 50%;\n    color: var(--Color, #023F88);\n    font-size: 3.5rem;\n    font-style: normal;\n    font-weight: 700;\n    line-height: normal;\n    text-transform: uppercase;\n}\n\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.fix-section {\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\n    padding: 4.44rem var(--section) 16.45rem;\n    overflow: hidden;\n}\n\n\n.appointment .item label {\n    font-size: 14px;\n    font-weight: 500;\n    position: absolute;\n    z-index: 1;\n    background: #fff;\n    left: 10px;\n    top: 10px;\n    padding: 0 10px;\n    display: inline-block;\n    width: auto;\n    border-radius: 8px;\n    color: #333;\n}\n.appointment {\n    background: #fff;\n    position: relative;\n    z-index: 1;\n}\n\n\n#header .header-nav-main>.menu-item>a {\n    color: #404040;\n    font-size: 1.1rem;\n    font-style: normal;\n	transition: color 0.3s ease;\n    font-weight: 600;\n    line-height: 1.35rem;\n    padding: var(--30) 0;\n}\n#header .header-nav-main > .menu-item.current-menu-item > a {\n    color: #023f88; /* Màu xanh dương */\n}\n#header .header-nav-main > .menu-item > a:hover {\n    color: #023f88; /* Màu xanh dương */\n}\n\n\n.phongvt-hieu-ung-toa-hinh {\n    display: block;\n    position: relative;\n    overflow: hidden\n}\n\n.phongvt-hieu-ung-toa-hinh:before {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    z-index: 2;\n    display: block;\n    content: \'\';\n    width: 0;\n    height: 0;\n    background: rgba(255,255,255,0.2);\n    border-radius: 100%;\n    opacity: 0;\n    -webkit-transform: translate(-50%, -50%);\n    -ms-transform: translate(-50%, -50%);\n    -o-transform: translate(-50%, -50%);\n    transform: translate(-50%, -50%)\n}\n\n@media (min-width: 1025px) {\n    .phongvt-hieu-ung-toa-hinh:hover:before {\n        -webkit-animation:circle 0.75s;\n        -ms-animation: circle 0.75s;\n        -o-animation: circle 0.75s;\n        animation: circle 0.75s\n    }\n}\n\n@-ms-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-o-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-webkit-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}', 'flatsome-child', '', 'inherit', 'closed', 'closed', '', '852-revision-v1', '', '', '2025-04-22 23:57:42', '2025-04-22 16:57:42', '', 852, 'http://localhost/vionis/?p=1080', 0, 'revision', '', 0);
