 flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.fix-section {\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\n    padding: 4.44rem var(--section) 16.45rem;\n    overflow: hidden;\n}\n\n\n.appointment .item label {\n    font-size: 14px;\n    font-weight: 500;\n    position: absolute;\n    z-index: 1;\n    background: #fff;\n    left: 10px;\n\n    padding: 0 10px;\n    display: inline-block;\n    width: auto;\n    border-radius: 8px;\n    color: #333;\n}\n.appointment {\n    background: #fff;\n    position: relative;\n    z-index: 1;\n}\n\n\n#header .header-nav-main>.menu-item>a {\n    color: #404040;\n    font-size: 1.1rem;\n    font-style: normal;\n	transition: color 0.3s ease;\n    font-weight: 600;\n    line-height: 1.35rem;\n    padding: var(--30) 0;\n}\n#header .header-nav-main > .menu-item.current-menu-item > a {\n    color: #023f88; /* Màu xanh dương */\n}\n#header .header-nav-main > .menu-item > a:hover {\n    color: #023f88; /* Màu xanh dương */\n}\n\n\n.phongvt-hieu-ung-toa-hinh {\n    display: block;\n    position: relative;\n    overflow: hidden\n}\n\n.phongvt-hieu-ung-toa-hinh:before {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    z-index: 2;\n    display: block;\n    content: \'\';\n    width: 0;\n    height: 0;\n    background: rgba(255,255,255,0.2);\n    border-radius: 100%;\n    opacity: 0;\n    -webkit-transform: translate(-50%, -50%);\n    -ms-transform: translate(-50%, -50%);\n    -o-transform: translate(-50%, -50%);\n    transform: translate(-50%, -50%)\n}\n\n@media (min-width: 1025px) {\n    .phongvt-hieu-ung-toa-hinh:hover:before {\n        -webkit-animation:circle 0.75s;\n        -ms-animation: circle 0.75s;\n        -o-animation: circle 0.75s;\n        animation: circle 0.75s\n    }\n}\n\n@-ms-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-o-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-webkit-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}', 'flatsome-child', '', 'inherit', 'closed', 'closed', '', '852-revision-v1', '', '', '2025-04-28 10:12:39', '2025-04-28 03:12:39', '', 852, 'http://localhost/vionis/?p=1114', 0, 'revision', '', 0),
