(1301, 6, '2026-06-01 10:43:32', '2026-06-01 03:43:32', '.gtranslate-custom {\n    text-align: right;\n}\n\n\n/* Giao diện GTranslate */\n.gtranslate-custom select {\n    background-color: #ffffff;\n    color: #222;\n    border: 1px solid #ddd;\n    border-radius: 8px;\n    padding: 6px 10px;\n    font-size: 15px;\n    box-shadow: 0 1px 4px rgba(0,0,0,0.08);\n    cursor: pointer;\n    transition: all 0.3s ease;\n}\n\n/* Hover select */\n.gtranslate-custom select:hover {\n    border-color: #0073e6;\n    background-color: #f0f8ff;\n}\n\n/* Link ngôn ngữ */\n.gtranslate-custom a {\n    display: inline-flex;\n    align-items: center;\n    text-decoration: none;\n    padding: 6px 10px;\n    margin: 5px 3px;\n    background: #f9f9f9;\n    color: #333;\n    border: 1px solid #ddd;\n    border-radius: 6px;\n    font-size: 14px;\n    transition: all 0.3s;\n}\n\n/* Icon cờ quốc gia trong link */\n.gtranslate-custom a img {\n    width: 20px;\n    height: 14px;\n    margin-right: 5px;\n    object-fit: cover;\n}\n\n/* Hover link */\n.gtranslate-custom a:hover {\n    background: #0073e6;\n    color: #fff;\n    border-color: #0073e6;\n}\n\n/* Responsive Mobile */\n@media (max-width: 768px) {\n    .gtranslate-custom {\n        display: flex;\n        justify-content: center; /* Căn giữa */\n        align-items: center;\n        flex-wrap: nowrap; /* Không cho xuống hàng */\n        gap: 5px;\n    }\n    .gtranslate-custom a {\n        flex: 0 0 auto;\n        padding: 4px 8px;\n        font-size: 13px;\n    }\n    .gtranslate-custom a img {\n        width: 16px; /* Icon nhỏ hơn */\n        height: 12px;\n        margin-right: 3px;\n    }\n}\n\n\n\n\n\n\n.has-hover .bg,\n.has-hover [class*=image-] img {\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\n    transform-origin: center center;\n}\n\n/* Khi hover */\n.has-hover:hover .bg,\n.has-hover:hover [class*=image-] img {\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /*