(255,255,255,0.2);\\n    border-radius: 100%;\\n    opacity: 0;\\n    -webkit-transform: translate(-50%, -50%);\\n    -ms-transform: translate(-50%, -50%);\\n    -o-transform: translate(-50%, -50%);\\n    transform: translate(-50%, -50%)\\n}\\n\\n@media (min-width: 1025px) {\\n    .phongvt-hieu-ung-toa-hinh:hover:before {\\n        -webkit-animation:circle 0.75s;\\n        -ms-animation: circle 0.75s;\\n        -o-animation: circle 0.75s;\\n        animation: circle 0.75s\\n    }\\n}\\n\\n@-ms-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-o-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-webkit-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-06-26 04:41:46\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'e98ab291-f6cb-4c51-8382-2cfb95310a8b', '', '', '2026-06-26 11:41:46', '2026-06-26 04:41:46', '', 0, 'http://localhost/vionis/e98ab291-f6cb-4c51-8382-2cfb95310a8b/', 0, 'customize_changeset', '', 0);
