ng */\\n}\\n\\n\\n.phongvt-hieu-ung-toa-hinh {\\n    display: block;\\n    position: relative;\\n    overflow: hidden\\n}\\n\\n.phongvt-hieu-ung-toa-hinh:before {\\n    position: absolute;\\n    top: 50%;\\n    left: 50%;\\n    z-index: 2;\\n    display: block;\\n    content: \'\';\\n    width: 0;\\n    height: 0;\\n    background: rgba(255,255,255,0.2);\\n    border-radius: 100%;\\n    opacity: 0;\\n    -webkit-transform: translate(-50%, -50%);\\n    -ms-transform: translate(-50%, -50%);\\n    -o-transform: translate(-50%, -50%);\\n    transform: translate(-50%, -50%)\\n}\\n\\n@media (min-width: 1025px) {\\n    .phongvt-hieu-ung-toa-hinh:hover:before {\\n        -webkit-animation:circle 0.75s;\\n        -ms-animation: circle 0.75s;\\n        -o-animation: circle 0.75s;\\n        animation: circle 0.75s\\n    }\\n}\\n\\n@-ms-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-o-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-webkit-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 6,\n        \"date_modified_gmt\": \"2026-07-10 07:35:00\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '22f6017f-0985-4ec4-a1c5-a41403b26cb6', '', '', '2026-07-10 14:35:00', '2026-07-10 07:35:00', '', 0, 'http://localhost/vionis/22f6017f-0985-4ec4-a1c5-a41403b26cb6/', 