ransition:.3s;\n}\n\n.footer-social a i{\n    width:auto;\n    margin:0;\n    color:#fff;\n    font-size:16px;\n}\n\n.footer-social img{\n    width:22px;\n    height:22px;\n    display:block;\n    object-fit:contain;\n    margin:auto;\n    vertical-align:middle;\n}\n\n/* hover chung */\n.footer-social a:hover{\n    background:#fff;\n    transform:translateY(-2px);\n}\n\n.footer-social a:hover i{\n    color:#0071BB;\n}\n\n/* riêng Zalo */\n.footer-social .zalo-social:hover{\n    background:rgba(255,255,255,.25);\n}\n\n.footer-social .zalo-social:hover img{\n    transform:scale(1.08);\n}\n/* ==========================\n   MAP\n========================== */\n\n.footer-map iframe{\n    width:100%;\n    height:260px;\n    border:none;\n    border-radius:10px;\n    overflow:hidden;\n    box-shadow:0 8px 20px rgba(0,0,0,.15);\n}\n\n/* ==========================\n   RESPONSIVE\n========================== */\n\n@media (max-width:992px){\n\n.vionis-footer .footer-grid{\n    grid-template-columns:repeat(2,1fr);\n    gap:35px;\n}\n\n}\n\n@media (max-width:768px){\n\n.vionis-footer{\n    padding:50px 0;\n}\n\n.vionis-footer .footer-grid{\n    grid-template-columns:1fr;\n    gap:40px;\n}\n\n.vionis-footer h3{\n    font-size:24px;\n    margin-bottom:20px;\n}\n\n.footer-map iframe{\n    height:300px;\n}\n\n}\n\n@media (max-width:480px){\n\n.vionis-footer{\n    padding:40px 0;\n}\n\n.vionis-footer h3{\n    font-size:22px;\n}\n\n.vionis-footer li{\n    font-size:15px;\n}\n\n.footer-social a{\n    width:42px;\n    height:42px;\n}\n\n.footer-social a i{\n    font-size:18px;\n}\n\n.footer-map iframe{\n    height:250px;\n}\n\n}\n\n</style>\n\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css\">\n\n<div class=\"vionis-footer\">\n\n<div class=\"footer-grid\">\n\n<!-- Information -->\n<div>\n\n<h3>Information</h3>\n\n<ul>\n\n<li>\n<i class=\"fa-regular fa-map\"></i>\n<span>\nAddress in Vietnam:<br>\nDong 1 Hamlet, Kep Commune,<br>\nBac