grid .overlay{\n    position:absolute;\n    inset:0;\n    background:linear-gradient(\n        to bottom,\n        rgba(0,0,0,.08),\n        rgba(0,0,0,.22),\n        rgba(0,0,0,.28)\n    );\n    transition:.35s;\n}\n\n.vionis-tour-grid .content{\n    position:absolute;\n    inset:0;\n    display:flex;\n    justify-content:center;\n    align-items:center;\n    padding:25px;\n    z-index:2;\n}\n\n.vionis-tour-grid h3{\n    margin:0;\n    padding:0;\n\n    color:#fff;\n    font-family:\"Montserrat\",sans-serif;\n    font-size:46px;\n    font-weight:800;\n    line-height:1.05;\n    text-align:center;\n    text-transform:uppercase;\n\n    letter-spacing:0;\n\n    /* bỏ viền chữ để không bị gãy nét */\n    -webkit-text-stroke:0;\n\n    /* shadow nhẹ và mịn */\n    text-shadow:\n        0 2px 4px rgba(0,0,0,.45),\n        0 6px 16px rgba(0,0,0,.35);\n\n    transition:all .35s ease;\n}\n\n.vionis-tour-grid .tour-card:hover img{\n    transform:scale(1.08);\n}\n\n.vionis-tour-grid .tour-card:hover .overlay{\n    background:linear-gradient(\n        to bottom,\n        rgba(0,0,0,.18),\n        rgba(0,0,0,.32),\n        rgba(0,0,0,.42)\n    );\n}\n\n.vionis-tour-grid .tour-card:hover h3{\n    transform:scale(1.03);\n}\n\n/* Tablet */\n\n@media(max-width:992px){\n\n.vionis-tour-grid{\n    grid-template-columns:repeat(2,1fr);\n}\n\n.vionis-tour-grid .tour-card{\n    height:360px;\n}\n\n.vionis-tour-grid h3{\n    font-size:34px;\n}\n\n}\n\n/* Mobile */\n\n@media(max-width:549px){\n\n.vionis-tour-grid{\n    grid-template-columns:1fr;\n}\n\n.vionis-tour-grid .tour-card{\n    height:280px;\n}\n\n.vionis-tour-grid h3{\n    font-size:24px;\n    line-height:1.15;\n}\n\n}\n</style>\n[/ux_html]\n[ux_html]\n\n<div class=\"vionis-tour-grid\">\n\n    <a class=\"tour-card\" href=\"/danh-muc-san-pham/north-vietnam/\">\n        <img src=\"http://localhost/vionis/wp-content/uploads/2026/07/Northern-Vietnam-Tours.jpg\" alt=\"North Vietnam Tour\">\n        <div class=\"overlay\"></div>\n        