\n\n/* Hover select */\n.gtranslate-custom select:hover {\n    border-color: #0073e6;\n    background-color: #f0f8ff;\n}\n\n/* Link ngôn ngữ */\n.gtranslate-custom a {\n    display: inline-flex;\n    align-items: center;\n    text-decoration: none;\n    padding: 6px 10px;\n    margin: 5px 3px;\n    background: #f9f9f9;\n    color: #333;\n    border: 1px solid #ddd;\n    border-radius: 6px;\n    font-size: 14px;\n    transition: all 0.3s;\n}\n\n/* Icon cờ quốc gia trong link */\n.gtranslate-custom a img {\n    width: 20px;\n    height: 14px;\n    margin-right: 5px;\n    object-fit: cover;\n}\n\n/* Hover link */\n.gtranslate-custom a:hover {\n    background: #0073e6;\n    color: #fff;\n    border-color: #0073e6;\n}\n\n/* Responsive Mobile */\n@media (max-width: 768px) {\n    .gtranslate-custom {\n        display: flex;\n        justify-content: center; /* Căn giữa */\n        align-items: center;\n        flex-wrap: nowrap; /* Không cho xuống hàng */\n        gap: 5px;\n    }\n    .gtranslate-custom a {\n        flex: 0 0 auto;\n        padding: 4px 8px;\n        font-size: 13px;\n    }\n    .gtranslate-custom a img {\n        width: 16px; /* Icon nhỏ hơn */\n        height: 12px;\n        margin-right: 3px;\n    }\n}\n\n.has-hover .bg,\n.has-hover [class*=image-] img {\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\n    transform-origin: center center;\n}\n\n/* Khi hover */\n.has-hover:hover .bg,\n.has-hover:hover [class*=image-] img {\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /* chuyển động nhẹ lên */\n    filter: brightness(1.2) contrast(1.1) saturate(1.2); /* giảm độ sáng và bão hòa */\n    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4), \n                0 0 40px rgba(255, 255, 255, 0.3), \n                0 0 60px rgba(255, 255, 255, 0.2), \n                0 5px 10px rgba(0, 0, 0, 0.1); /* bóng đổ mềm */\n    opacity: 1;\n}\n\n\n\n.box-text a:not(.button),\n.box-text h4,\n.box-text h5,\n.box-text h6 {\n    line-height: 1.3;\n    color: rgb(211 27 27);\n    margin-bottom: .1em;\n    margin-top: .1em;\n    transition: color 0.3s ease, transform 0.3s ease;\n}\n\n.box-text a:not(.button):hover,\n.box-text h4:hover,\n.box-text h5:hover,\n.box-text h6:hover {\n    color: rgb(255, 0, 0);\n    transform: translateY(-3px);\n    cursor: pointer;\n}\n\n\n\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 22px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n}\n.home_blog .box-blog-post {\n    box-shadow: 0 0 18px rgba(0, 0, 0, 0.05);\n    border-radius: 10px; /* Bo góc */\n    transition: all 0.s ease;\n}\n.home_blog .box-blog-post:hover {\n    box-shadow: 0 0px 5px #84c8ff;\n    transform: scale(1.02);\n    padding: 10px 20px;\n    text-align: left;\n    border: 1px solid rgba(0, 0, 0, 0.05); /* Giữ viền khi hover */\n}\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.tour-outbound .tour-outbound__title h2 {\n    color: #fff;\n    font-size: clamp(1.8rem, 5vw, 3.5rem);\n    font-style: normal;\n    font-weight: 700;\n    line-height: 1.2;\n    text-transform: uppercase;\n}\n\n.home-introduce .home-introduce__title h1 {\n    margin-bottom: 1.06rem;\n}\n\n.phongvt-title-main h2,\n.phongvt-title-main h1,\n.phongvt-title-main h3,\n.phongvt-title-main-p p {\n    object-position: 50% 50%;\n    color: var(--Color, #023F88);\n    font-size: 3.5rem;\n    font-style: normal;\n    font-weight: 700;\n    line-height: normal;\n    text-transform: uppercase;\n}\n\n/* Tablet */\n@media (max-width: 991px) {\n    .phongvt-title-main h2,\n    .phongvt-title-main h1,\n    .phongvt-title-main h3,\n    .phongvt-title-main-p p {\n        font-size: 2.5rem;\n    }\n}\n\n/* Mobile */\n@media (max-width: 767px) {\n    .phongvt-title-main h2,\n    .phongvt-title-main h1,\n    .phongvt-title-main h3,\n    .phongvt-title-main-p p {\n        font-size: 1.8rem;\n        line-height: 1.3;\n    }\n}\n\n\n\n.tour-outbound {\n    padding: 4.18rem var(--section) 8.81rem;\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\n    display: flex\n;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n\n.fix-section {\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\n    padding: 4.44rem var(--section) 16.45rem;\n    overflow: hidden;\n}\n\n\n.appointment .item label {\n    font-size: 14px;\n    font-weight: 500;\n    position: absolute;\n    z-index: 1;\n    background: #fff;\n    left: 10px;\n\n    padding: 0 10px;\n    display: inline-block;\n    width: auto;\n    border-radius: 8px;\n    color: #333;\n}\n.appointment {\n    background: #fff;\n    position: relative;\n    z-index: 1;\n}\n\n\n#header .header-nav-main>.menu-item>a {\n    color: #404040;\n    font-size: 1.1rem;\n    font-style: normal;\n	transition: color 0.3s ease;\n    font-weight: 600;\n    line-height: 1.35rem;\n    padding: var(--30) 0;\n}\n#header .header-nav-main > .menu-item.current-menu-item > a {\n    color: #023f88; /* Màu xanh dương */\n}\n#header .header-nav-main > .menu-item > a:hover {\n    color: #023f88; /* Màu xanh dương */\n}\n\n\n.phongvt-hieu-ung-toa-hinh {\n    display: block;\n    position: relative;\n    overflow: hidden\n}\n\n.phongvt-hieu-ung-toa-hinh:before {\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    z-index: 2;\n    display: block;\n    content: \'\';\n    width: 0;\n    height: 0;\n    background: rgba(255,255,255,0.2);\n    border-radius: 100%;\n    opacity: 0;\n    -webkit-transform: translate(-50%, -50%);\n    -ms-transform: translate(-50%, -50%);\n    -o-transform: translate(-50%, -50%);\n    transform: translate(-50%, -50%)\n}\n\n@media (min-width: 1025px) {\n    .phongvt-hieu-ung-toa-hinh:hover:before {\n        -webkit-animation:circle 0.75s;\n        -ms-animation: circle 0.75s;\n        -o-animation: circle 0.75s;\n        animation: circle 0.75s\n    }\n}\n\n@-ms-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-o-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@-webkit-keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}\n\n@keyframes circle {\n    0% {\n        opacity: 1\n    }\n\n    40% {\n        opacity: 1\n    }\n\n    100% {\n        width: 200%;\n        height: 200%;\n        opacity: 0\n    }\n}', 'flatsome-child', '', 'inherit', 'closed', 'closed', '', '852-revision-v1', '', '', '2026-07-10 21:42:59', '2026-07-10 14:42:59', '', 852, 'https://vionistravel.com/?p=1703', 0, 'revision', '', 0),
(1704, 6, '2026-07-10 21:44:54', '2026-07-10 14:44:54', '[section bg=\"1681\" bg_size=\"original\" bg_overlay=\"rgba(0, 0, 0, 0.6)\" bg_pos=\"37% 63%\" dark=\"true\" padding=\"0px\" height=\"50vh\" height__sm=\"100vh\" height__md=\"60vh\" video_mp4=\"/wp-content/uploads/2026/07/Web-du-lich.mp4\" video_visibility=\"visible\"]\n\n[row]\n\n[col span__sm=\"12\" align=\"center\"]\n\n[ux_text font_size=\"3\" font_size__sm=\"2\" text_align=\"center\" class=\"extra mg0\"]\n\n<strong>Vionis Travel – Your trusted travel partner for every journey. </strong>\n[/ux_text]\n[ux_text font_size=\"2.5\" font_size__sm=\"1\"]\n\nYour Perfect Trip Starts Here\n[/ux_text]\n[row_inner]\n\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[search style=\"flat\" size=\"xlarge\" visibility=\"hidden\"]\n\n[ux_html]\n\n[tour_search_filter]\n[/ux_html]\n\n[/col_inner]\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg_color=\"rgba(18, 127, 175, 0.064)\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"0px 0px 0px 0px\"]\n\n[ux_product_categories style=\"default\" columns__sm=\"1\" slider_nav_style=\"circle\" slider_nav_position=\"outside\" ids=\"43,44,45,53\" orderby=\"name\" show_count=\"0\" image_width=\"33\" image_size=\"original\" text_align=\"left\" visibility=\"hidden\"]\n\n[vionis_tour_categories ids=\"43,44,45,53\"]\n\n\n[/col]\n\n[/row]\n[row]\n\n[col span=\"6\" span__sm=\"12\" span__md=\"12\"]\n\n[gap height=\"70px\" visibility=\"hide-for-medium\"]\n\n[ux_text class=\"phongvt-title-main\"]\n\n<h2><strong>Vionis Travel</strong>\r\n<strong>we save your satisfied</strong></h2>\n[/ux_text]\n[gap]\n\n[ux_text font_size=\"1.2\" line_height=\"1.5\"]\n\n<span style=\"font-size: 16px;\">Welcome to Vionis Travel! More than just simply providing trips, we craft complete journeys, where you are free to explore the world without having to worry about anything.</span>\r\n<span style=\"font-size: 16px;\">Over the past 15 years, \"safety\" and \"satisfaction\" have not just been slogans, but commitments, a guiding principle for all of Safetours\' activities.</span>\n[/ux_text]\n[gap]\n\n[row_inner]\n\n[col_inner span=\"4\" span__sm=\"12\"]\n\n[button text=\"About us\" style=\"outline\" size=\"larger\" radius=\"35\" expand=\"true\" icon=\"icon-angle-right\" link=\"/about\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n[col span=\"6\" span__sm=\"12\" span__md=\"12\" margin=\"70px 0px 0px 0px\" margin__sm=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1605\" image_size=\"original\" class=\"img-radius phongvt-hieu-ung-toa-hinh\"]\n\n\n[/col]\n\n[/row]\n[row width=\"custom\" custom_width=\"1700px\"]\n\n[col span__sm=\"12\" margin=\"30px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"left\" class=\"phongvt-title-main h2\"]\n\n<h2>Explore Yacht Tour</h2>\n[/ux_text]\n[ux_products style=\"normal\" width=\"full-width\" columns__sm=\"1\" columns__md=\"2\" slider_nav_style=\"simple\" show_quick_view=\"0\" equalize_box=\"true\" cat=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n[gap]\n\n[row_inner]\n\n[col_inner span__sm=\"12\" align=\"center\"]\n\n[button text=\"Explore now\" size=\"large\" radius=\"99\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/yacht-tour\" target=\"_blank\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section label=\"tour-outbound\" class=\"tour-outbound fix-section\"]\n\n[row]\n\n[col span=\"5\" span__sm=\"12\" color=\"light\"]\n\n[gap height=\"120px\" visibility=\"hide-for-medium\"]\n\n[ux_text font_size=\"1.5\" class=\"tour-outbound__title\"]\n\n<h2>North Vietnam Tours</h2>\n[/ux_text]\n[ux_text font_size=\"1.2\" line_height=\"1.5\"]\n\nVionis Travel focuses on every small detail, from selecting a suitable itinerary, to creating unique experiential activities, helping you explore local culture in the most authentic way.\n[/ux_text]\n[gap]\n\n[button text=\"Explore now\" size=\"larger\" radius=\"38\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/north-vietnam\" target=\"_blank\"]\n\n\n[/col]\n[col span=\"1\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col]\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_products style=\"normal\" columns=\"1\" slider_nav_style=\"simple\" slider_nav_color=\"light\" equalize_box=\"true\" cat=\"43\" orderby=\"title\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n\n[/col]\n\n[/row]\n\n[/section]\n[section label=\"tour-outbound\" bg=\"892\" bg_size=\"original\" bg_pos=\"36% 0%\"]\n\n[row]\n\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_products style=\"normal\" type=\"slider-full\" slider_nav_style=\"simple\" equalize_box=\"true\" cat=\"44\" products=\"4\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n\n[/col]\n[col span=\"1\" span__sm=\"12\"]\n\n\n[/col]\n[col span=\"5\" span__sm=\"12\" color=\"light\"]\n\n[gap height=\"150px\" visibility=\"hide-for-medium\"]\n\n[ux_text font_size=\"1.5\" class=\"phongvt-title-main\"]\n\n<h2>Central VietNam Tours</h2>\n[/ux_text]\n[ux_text font_size=\"1.2\" line_height=\"1.5\" text_color=\"rgb(0,0,0)\"]\n\nVionis Travel focuses on every small detail, from selecting a suitable itinerary, to creating unique experiential activities, helping you explore local culture in the most authentic way.\n[/ux_text]\n[gap]\n\n[button text=\"Explore now\" size=\"larger\" radius=\"38\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/central-vietnam\" target=\"_blank\"]\n\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"920\" bg_size=\"original\" bg_color=\"rgba(244, 244, 244, 0.122)\" bg_overlay=\"rgba(255, 255, 255, 0.552)\" bg_pos=\"71% 0%\" dark=\"true\" class=\"fix-section\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"50px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main\"]\n\n<h2>South Vietnam Tours</h2>\n[/ux_text]\n[ux_products style=\"normal\" columns__sm=\"1\" slider_nav_style=\"simple\" equalize_box=\"true\" cat=\"45\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n[gap]\n\n[row_inner]\n\n[col_inner span__sm=\"12\" padding=\"0px 0px 0px 0px\" margin=\"0px 0px 0px 0px\" align=\"center\"]\n\n[button text=\"Explore now\" size=\"large\" radius=\"38\" expand=\"0\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/south-vietnam\" target=\"_blank\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"892\" visibility=\"hide-for-medium\"]\n\n[row class=\"padding-bot\"]\n\n[col span__sm=\"12\" margin=\"40px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h2>FEEDBACK FROM CUSTOMERS</h2>\n[/ux_text]\n\n[/col]\n\n[/row]\n[row]\n\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"896\" image_width=\"121\" name=\"Emma Wilson\" company=\"Australia\"]\n\n<p>“Vionis Travel provided an outstanding Vietnam tour experience. The itinerary was well organized, the hotels were comfortable, and the guide was extremely professional. Everything exceeded our expectations.”</p>\n\n[/testimonial]\n\n[/col]\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"898\" image_width=\"121\" name=\"Sophia Miller\" company=\"Canada\"]\n\n<p>“The Ha Long Bay cruise arranged by Vionis Travel was unforgettable. From transportation to activities, every detail was carefully prepared. Highly recommended for anyone visiting Vietnam.”</p>\n\n[/testimonial]\n\n[/col]\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"1627\" image_width=\"121\" name=\"Daniel Kim\" company=\"South Korea\"]\n\n<p>“Our family trip to Vietnam was fantastic thanks to Vionis Travel. Every part of the journey was organized professionally, from airport transfers to sightseeing activities. The team was responsive, reliable, and always available whenever we needed assistance. It was one of the best travel experiences we’ve ever had.”</p>\n\n[/testimonial]\n\n[/col]\n\n[/row]\n\n[/section]\n[row]\n\n[col span__sm=\"12\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h3>Travel Guide</h3>\n[/ux_text]\n[blog_posts style=\"normal\" columns=\"3\" columns__md=\"1\" slider_nav_style=\"simple\" badge_style=\"square\" excerpt_length=\"26\" show_category=\"text\" image_height=\"65.25%\" image_radius=\"4\" image_size=\"original\" image_hover=\"zoom\" text_align=\"left\"]\n\n\n[/col]\n\n[/row]\n[section bg=\"1633\" bg_size=\"original\" bg_overlay=\"rgba(0, 0, 0, 0.4)\" bg_pos=\"70% 60%\" border=\"0px 0px 0px 0px\" border_margin=\"0px 0px 0px 0px\"]\n\n[gap height=\"90px\" visibility=\"hide-for-medium\"]\n\n[row]\n\n[col span__sm=\"12\" class=\"vis\"]\n\n[ux_text text_align=\"center\" class=\"trust\"]\n\n<h2>Every Great Journey Starts with Trust</h2>\n<h4 class=\"thin-font\">ll the suggestions, advice and instructions that Lily’s Travel has accumulated to become tips to help your trips become more attractive, interesting and significant.</h4>\n[/ux_text]\n\n[/col]\n\n[/row]\n[row width=\"custom\" h_align=\"center\"]\n\n[col span=\"10\" span__sm=\"12\" span__md=\"12\"]\n\n[row_inner h_align=\"center\"]\n\n[col_inner span=\"2\" span__sm=\"7\" span__md=\"3\" padding=\"30px 30px 30px 30px\" bg_color=\"rgb(255, 255, 255)\" border=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1611\" image_hover_alt=\"zoom\"]\n\n\n[/col_inner]\n[col_inner span=\"2\" span__sm=\"7\" span__md=\"3\" padding=\"30px 30px 30px 30px\" bg_color=\"rgb(255, 255, 255)\" border=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1616\" image_hover_alt=\"zoom\" link=\"https://share.google/cJWr03bpmlOJfILIF\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"563\" bg_size=\"original\" bg_overlay=\"rgba(238, 224, 224, 0.331)\" bg_pos=\"57% 0%\" border=\"0px 0px 0px 0px\" visibility=\"hidden\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"0px 0px -40px 0px\"]\n\n[row_inner]\n\n[col_inner span=\"7\" span__sm=\"12\" class=\"appointment\"]\n\n[gap height=\"90px\" visibility=\"hide-for-medium\"]\n\n[gap visibility=\"show-for-small\"]\n\n[ux_text text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h2>Connect with Vionis Travel</h2>\n[/ux_text]\n[contact-form-7 id=\"87\"]\n\n\n[/col_inner]\n[col_inner span=\"5\" span__sm=\"12\" class=\"appointment\"]\n\n[ux_image id=\"912\" image_size=\"original\" class=\"phongvt-hieu-ung-toa-hinh\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]', 'Homepage', '', 'inherit', 'closed', 'closed', '', '1138-revision-v1', '', '', '2026-07-10 21:44:54', '2026-07-10 14:44:54', '', 1138, 'https://vionistravel.com/?p=1704', 0, 'revision', '', 0),
(1705, 6, '2026-07-10 21:45:05', '2026-07-10 14:45:05', '[section bg=\"1681\" bg_size=\"original\" bg_overlay=\"rgba(0, 0, 0, 0.6)\" bg_pos=\"37% 63%\" dark=\"true\" padding=\"0px\" height=\"50vh\" height__sm=\"100vh\" height__md=\"60vh\" video_mp4=\"/wp-content/uploads/2026/07/Web-du-lich.mp4\" video_visibility=\"visible\"]\n\n[row]\n\n[col span__sm=\"12\" align=\"center\"]\n\n[ux_text font_size=\"3\" font_size__sm=\"2\" text_align=\"center\" class=\"extra mg0\"]\n\n<strong>Vionis Travel – Your trusted travel partner for every journey. </strong>\n[/ux_text]\n[ux_text font_size=\"2.5\" font_size__sm=\"1\"]\n\nYour Perfect Trip Starts Here\n[/ux_text]\n[row_inner]\n\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[search style=\"flat\" size=\"xlarge\" visibility=\"hidden\"]\n\n[ux_html]\n\n[tour_search_filter]\n[/ux_html]\n\n[/col_inner]\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg_color=\"rgba(18, 127, 175, 0.064)\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"30px 0px 0px 0px\"]\n\n[ux_product_categories style=\"default\" columns__sm=\"1\" slider_nav_style=\"circle\" slider_nav_position=\"outside\" ids=\"43,44,45,53\" orderby=\"name\" show_count=\"0\" image_width=\"33\" image_size=\"original\" text_align=\"left\" visibility=\"hidden\"]\n\n[vionis_tour_categories ids=\"43,44,45,53\"]\n\n\n[/col]\n\n[/row]\n[row]\n\n[col span=\"6\" span__sm=\"12\" span__md=\"12\"]\n\n[gap height=\"70px\" visibility=\"hide-for-medium\"]\n\n[ux_text class=\"phongvt-title-main\"]\n\n<h2><strong>Vionis Travel</strong>\r\n<strong>we save your satisfied</strong></h2>\n[/ux_text]\n[gap]\n\n[ux_text font_size=\"1.2\" line_height=\"1.5\"]\n\n<span style=\"font-size: 16px;\">Welcome to Vionis Travel! More than just simply providing trips, we craft complete journeys, where you are free to explore the world without having to worry about anything.</span>\r\n<span style=\"font-size: 16px;\">Over the past 15 years, \"safety\" and \"satisfaction\" have not just been slogans, but commitments, a guiding principle for all of Safetours\' activities.</span>\n[/ux_text]\n[gap]\n\n[row_inner]\n\n[col_inner span=\"4\" span__sm=\"12\"]\n\n[button text=\"About us\" style=\"outline\" size=\"larger\" radius=\"35\" expand=\"true\" icon=\"icon-angle-right\" link=\"/about\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col_inner]\n[col_inner span=\"4\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n[col span=\"6\" span__sm=\"12\" span__md=\"12\" margin=\"70px 0px 0px 0px\" margin__sm=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1605\" image_size=\"original\" class=\"img-radius phongvt-hieu-ung-toa-hinh\"]\n\n\n[/col]\n\n[/row]\n[row width=\"custom\" custom_width=\"1700px\"]\n\n[col span__sm=\"12\" margin=\"30px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"left\" class=\"phongvt-title-main h2\"]\n\n<h2>Explore Yacht Tour</h2>\n[/ux_text]\n[ux_products style=\"normal\" width=\"full-width\" columns__sm=\"1\" columns__md=\"2\" slider_nav_style=\"simple\" show_quick_view=\"0\" equalize_box=\"true\" cat=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n[gap]\n\n[row_inner]\n\n[col_inner span__sm=\"12\" align=\"center\"]\n\n[button text=\"Explore now\" size=\"large\" radius=\"99\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/yacht-tour\" target=\"_blank\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section label=\"tour-outbound\" class=\"tour-outbound fix-section\"]\n\n[row]\n\n[col span=\"5\" span__sm=\"12\" color=\"light\"]\n\n[gap height=\"120px\" visibility=\"hide-for-medium\"]\n\n[ux_text font_size=\"1.5\" class=\"tour-outbound__title\"]\n\n<h2>North Vietnam Tours</h2>\n[/ux_text]\n[ux_text font_size=\"1.2\" line_height=\"1.5\"]\n\nVionis Travel focuses on every small detail, from selecting a suitable itinerary, to creating unique experiential activities, helping you explore local culture in the most authentic way.\n[/ux_text]\n[gap]\n\n[button text=\"Explore now\" size=\"larger\" radius=\"38\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/north-vietnam\" target=\"_blank\"]\n\n\n[/col]\n[col span=\"1\" span__sm=\"12\" visibility=\"hide-for-medium\"]\n\n\n[/col]\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_products style=\"normal\" columns=\"1\" slider_nav_style=\"simple\" slider_nav_color=\"light\" equalize_box=\"true\" cat=\"43\" orderby=\"title\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n\n[/col]\n\n[/row]\n\n[/section]\n[section label=\"tour-outbound\" bg=\"892\" bg_size=\"original\" bg_pos=\"36% 0%\"]\n\n[row]\n\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_products style=\"normal\" type=\"slider-full\" slider_nav_style=\"simple\" equalize_box=\"true\" cat=\"44\" products=\"4\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n\n[/col]\n[col span=\"1\" span__sm=\"12\"]\n\n\n[/col]\n[col span=\"5\" span__sm=\"12\" color=\"light\"]\n\n[gap height=\"150px\" visibility=\"hide-for-medium\"]\n\n[ux_text font_size=\"1.5\" class=\"phongvt-title-main\"]\n\n<h2>Central VietNam Tours</h2>\n[/ux_text]\n[ux_text font_size=\"1.2\" line_height=\"1.5\" text_color=\"rgb(0,0,0)\"]\n\nVionis Travel focuses on every small detail, from selecting a suitable itinerary, to creating unique experiential activities, helping you explore local culture in the most authentic way.\n[/ux_text]\n[gap]\n\n[button text=\"Explore now\" size=\"larger\" radius=\"38\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/central-vietnam\" target=\"_blank\"]\n\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"920\" bg_size=\"original\" bg_color=\"rgba(244, 244, 244, 0.122)\" bg_overlay=\"rgba(255, 255, 255, 0.552)\" bg_pos=\"71% 0%\" dark=\"true\" class=\"fix-section\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"50px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main\"]\n\n<h2>South Vietnam Tours</h2>\n[/ux_text]\n[ux_products style=\"normal\" columns__sm=\"1\" slider_nav_style=\"simple\" equalize_box=\"true\" cat=\"45\" cat_exclude=\"53\" image_height=\"75%\" image_size=\"original\" image_hover=\"zoom\"]\n\n[gap]\n\n[row_inner]\n\n[col_inner span__sm=\"12\" padding=\"0px 0px 0px 0px\" margin=\"0px 0px 0px 0px\" align=\"center\"]\n\n[button text=\"Explore now\" size=\"large\" radius=\"38\" expand=\"0\" icon=\"icon-angle-right\" link=\"/danh-muc-san-pham/south-vietnam\" target=\"_blank\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"892\" visibility=\"hide-for-medium\"]\n\n[row class=\"padding-bot\"]\n\n[col span__sm=\"12\" margin=\"40px 0px 0px 0px\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h2>FEEDBACK FROM CUSTOMERS</h2>\n[/ux_text]\n\n[/col]\n\n[/row]\n[row]\n\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"896\" image_width=\"121\" name=\"Emma Wilson\" company=\"Australia\"]\n\n<p>“Vionis Travel provided an outstanding Vietnam tour experience. The itinerary was well organized, the hotels were comfortable, and the guide was extremely professional. Everything exceeded our expectations.”</p>\n\n[/testimonial]\n\n[/col]\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"898\" image_width=\"121\" name=\"Sophia Miller\" company=\"Canada\"]\n\n<p>“The Ha Long Bay cruise arranged by Vionis Travel was unforgettable. From transportation to activities, every detail was carefully prepared. Highly recommended for anyone visiting Vietnam.”</p>\n\n[/testimonial]\n\n[/col]\n[col span=\"4\" span__sm=\"12\"]\n\n[testimonial image=\"1627\" image_width=\"121\" name=\"Daniel Kim\" company=\"South Korea\"]\n\n<p>“Our family trip to Vietnam was fantastic thanks to Vionis Travel. Every part of the journey was organized professionally, from airport transfers to sightseeing activities. The team was responsive, reliable, and always available whenever we needed assistance. It was one of the best travel experiences we’ve ever had.”</p>\n\n[/testimonial]\n\n[/col]\n\n[/row]\n\n[/section]\n[row]\n\n[col span__sm=\"12\"]\n\n[ux_text font_size=\"2\" font_size__sm=\"1.45\" font_size__md=\"1.35\" text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h3>Travel Guide</h3>\n[/ux_text]\n[blog_posts style=\"normal\" columns=\"3\" columns__md=\"1\" slider_nav_style=\"simple\" badge_style=\"square\" excerpt_length=\"26\" show_category=\"text\" image_height=\"65.25%\" image_radius=\"4\" image_size=\"original\" image_hover=\"zoom\" text_align=\"left\"]\n\n\n[/col]\n\n[/row]\n[section bg=\"1633\" bg_size=\"original\" bg_overlay=\"rgba(0, 0, 0, 0.4)\" bg_pos=\"70% 60%\" border=\"0px 0px 0px 0px\" border_margin=\"0px 0px 0px 0px\"]\n\n[gap height=\"90px\" visibility=\"hide-for-medium\"]\n\n[row]\n\n[col span__sm=\"12\" class=\"vis\"]\n\n[ux_text text_align=\"center\" class=\"trust\"]\n\n<h2>Every Great Journey Starts with Trust</h2>\n<h4 class=\"thin-font\">ll the suggestions, advice and instructions that Lily’s Travel has accumulated to become tips to help your trips become more attractive, interesting and significant.</h4>\n[/ux_text]\n\n[/col]\n\n[/row]\n[row width=\"custom\" h_align=\"center\"]\n\n[col span=\"10\" span__sm=\"12\" span__md=\"12\"]\n\n[row_inner h_align=\"center\"]\n\n[col_inner span=\"2\" span__sm=\"7\" span__md=\"3\" padding=\"30px 30px 30px 30px\" bg_color=\"rgb(255, 255, 255)\" border=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1611\" image_hover_alt=\"zoom\"]\n\n\n[/col_inner]\n[col_inner span=\"2\" span__sm=\"7\" span__md=\"3\" padding=\"30px 30px 30px 30px\" bg_color=\"rgb(255, 255, 255)\" border=\"0px 0px 0px 0px\"]\n\n[ux_image id=\"1616\" image_hover_alt=\"zoom\" link=\"https://share.google/cJWr03bpmlOJfILIF\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg=\"563\" bg_size=\"original\" bg_overlay=\"rgba(238, 224, 224, 0.331)\" bg_pos=\"57% 0%\" border=\"0px 0px 0px 0px\" visibility=\"hidden\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"0px 0px -40px 0px\"]\n\n[row_inner]\n\n[col_inner span=\"7\" span__sm=\"12\" class=\"appointment\"]\n\n[gap height=\"90px\" visibility=\"hide-for-medium\"]\n\n[gap visibility=\"show-for-small\"]\n\n[ux_text text_align=\"center\" class=\"phongvt-title-main h2\"]\n\n<h2>Connect with Vionis Travel</h2>\n[/ux_text]\n[contact-form-7 id=\"87\"]\n\n\n[/col_inner]\n[col_inner span=\"5\" span__sm=\"12\" class=\"appointment\"]\n\n[ux_image id=\"912\" image_size=\"original\" class=\"phongvt-hieu-ung-toa-hinh\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]', 'Homepage', '', 'inherit', 'closed', 'closed', '', '1138-revision-v1', '', '', '2026-07-10 21:45:05', '2026-07-10 14:45:05', '', 1138, 'https://vionistravel.com/?p=1705', 0, 'revision', '', 0);
