ransition:.3s;\n}\n\n.footer-social a i{\n    width:auto;\n    margin:0;\n    color:#fff;\n    font-size:16px;\n}\n\n.footer-social img{\n    width:22px;\n    height:22px;\n    display:block;\n    object-fit:contain;\n    margin:auto;\n    vertical-align:middle;\n}\n\n/* hover chung */\n.footer-social a:hover{\n    background:#fff;\n    transform:translateY(-2px);\n}\n\n.footer-social a:hover i{\n    color:#0071BB;\n}\n\n/* riêng Zalo */\n.footer-social .zalo-social:hover{\n    background:rgba(255,255,255,.25);\n}\n\n.footer-social .zalo-social:hover img{\n    transform:scale(1.08);\n}\n/* ==========================\n   MAP\n========================== */\n\n.footer-map iframe{\n    width:100%;\n    height:260px;\n    border:none;\n    border-radius:10px;\n    overflow:hidden;\n    box-shadow:0 8px 20px rgba(0,0,0,.15);\n}\n\n/* ==========================\n   RESPONSIVE\n========================== */\n\n@media (max-width:992px){\n\n.vionis-footer .footer-grid{\n    grid-template-columns:repeat(2,1fr);\n    gap:35px;\n}\n\n}\n\n@media (max-width:768px){\n\n.vionis-footer{\n    padding:50px 0;\n}\n\n.vionis-footer .footer-grid{\n    grid-template-columns:1fr;\n    gap:40px;\n}\n\n.vionis-footer h3{\n    font-size:24px;\n    margin-bottom:20px;\n}\n\n.footer-map iframe{\n    height:300px;\n}\n\n}\n\n@media (max-width:480px){\n\n.vionis-footer{\n    padding:40px 0;\n}\n\n.vionis-footer h3{\n    font-size:22px;\n}\n\n.vionis-footer li{\n    font-size:15px;\n}\n\n.footer-social a{\n    width:42px;\n    height:42px;\n}\n\n.footer-social a i{\n    font-size:18px;\n}\n\n.footer-map iframe{\n    height:250px;\n}\n\n}\n\n</style>\n\n<link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css\">\n\n<div class=\"vionis-footer\">\n\n<div class=\"footer-grid\">\n\n<!-- Information -->\n<div>\n\n<h3>Information</h3>\n\n<ul>\n\n<li>\n<i class=\"fa-regular fa-map\"></i>\n<span>\nAddress in Vietnam:<br>\nDong 1 Hamlet, Kep Commune,<br>\nBac Ninh Province, Vietnam\n</span>\n</li>\n\n<li>\n<i class=\"fa-regular fa-envelope\"></i>\n<span>\nEmail (normally reply in 2 hours):<br>\n<a href=\"mailto:vionistravel@gmail.com\">\nvionistravel@gmail.com\n</a>\n</span>\n</li>\n\n<li>\n<i class=\"fa-regular fa-envelope\"></i>\n<span>\nBooking or request tour:<br>\n<a href=\"mailto:info@vionistravel.com\">\ninfo@vionistravel.com\n</a>\n</span>\n</li>\n\n<li>\n<i class=\"fa-regular fa-clock\"></i>\n<span>\nWork Time<br>\nMo-Sun: 8:30 - 21:30\n</span>\n</li>\n\n</ul>\n\n</div>\n\n<!-- Tours -->\n<div>\n\n<h3>Tours & Services</h3>\n\n<ul>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/north-vietnam/\">North Vietnam Tour</a>\n</li>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/central-vietnam/\">Central Vietnam Tour</a>\n</li>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/south-vietnam/\">South Vietnam Tour</a>\n</li>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/yacht-tour/\">Yacht Tour</a>\n</li>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/china-tour/\">China Tour</a>\n</li>\n\n<li>\n    <i class=\"fa-solid fa-chevron-right\"></i>\n    <a href=\"/danh-muc-san-pham/japan-tour/\">Japan Tour</a>\n</li>\n\n</ul>\n\n</div>\n\n<!-- Social -->\n<div>\n\n    <h3>Follow us on social</h3>\n\n    <div class=\"footer-social\">\n\n        <!-- Zalo -->\n        <a class=\"zalo-social\"\n   href=\"https://zalo.me/+84835219687\"\n   target=\"_blank\">\n    <img src=\"/wp-content/uploads/2026/06/zalo-icon.png\" alt=\"Zalo\">\n</a>\n\n        <!-- Facebook -->\n        <a href=\"https://www.facebook.com/vionistravel\"\n           target=\"_blank\"\n           rel=\"noopener noreferrer\"\n           aria-label=\"Facebook\">\n            <i class=\"fa-brands fa-facebook-f\"></i>\n        </a>\n\n        <!-- Instagram -->\n        <a href=\"https://www.instagram.com/vionis_travel/\"\n           target=\"_blank\"\n           rel=\"noopener noreferrer\"\n           aria-label=\"Instagram\">\n            <i class=\"fa-brands fa-instagram\"></i>\n        </a>\n\n        <!-- TikTok -->\n        <a href=\"https://www.tiktok.com/@vionis_travel\"\n           target=\"_blank\"\n           rel=\"noopener noreferrer\"\n           aria-label=\"TikTok\">\n            <i class=\"fa-brands fa-tiktok\"></i>\n        </a>\n\n        <!-- LinkedIn -->\n        <a href=\"https://www.linkedin.com/in/vionistravel/\"\n           target=\"_blank\"\n           rel=\"noopener noreferrer\"\n           aria-label=\"LinkedIn\">\n            <i class=\"fa-brands fa-linkedin-in\"></i>\n        </a>\n\n    </div>\n\n    <ul>\n\n        <li>\n            <i class=\"fa-solid fa-phone\"></i>\n            <span>\n                Tel:\n                <a href=\"tel:+84835219687\">\n                    +84 835 219 687\n                </a>\n            </span>\n        </li>\n\n        <li>\n            <i class=\"fa-brands fa-whatsapp\"></i>\n            <span>\n                WhatsApp:\n                <a href=\"https://wa.me/84835219687\"\n                   target=\"_blank\"\n                   rel=\"noopener noreferrer\">\n                    +84 835 219 687\n                </a>\n            </span>\n        </li>\n\n        <li>\n            <i class=\"fa-brands fa-line\"></i>\n            <span>Line: Updating...</span>\n        </li>\n\n        <li>\n            <i class=\"fa-brands fa-weixin\"></i>\n            <span>\n                WeChat:\n                <a href=\"https://vionistravel.com/wp-content/uploads/2026/07/wechat-vionis.jpg\" target=\"_blank\"\n                   rel=\"noopener noreferrer\">\n                    VionisTravel\n                </a>\n            </span>\n        </li>\n\n    </ul>\n\n</div>\n\n<!-- Map -->\n<div>\n\n<h3>Find us on map</h3>\n<div class=\"footer-map\">\n\n<iframe\nsrc=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d238040.05374482507!2d105.93989015411196!3d21.216939957652954!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x313569db473ed7af%3A0x823c58ac3fe61b2a!2sC%C3%94NG%20TY%20TNHH%20VIONIS%20TRAVEL!5e0!3m2!1svi!2s!4v1783679363373!5m2!1svi!2s\"\nstyle=\"border:0;\"\nallowfullscreen\nloading=\"lazy\"\nreferrerpolicy=\"strict-origin-when-cross-origin\">\n</iframe>\n\n</div>\n\n</div>\n\n</div>\n\n</div>\n[/ux_html]\n\n[/section]\n[section bg_color=\"rgb(0, 177, 255)\" dark=\"true\" padding=\"15px\"]\n\n[row class=\"padding-bot\"]\n\n[col span__sm=\"12\"]\n\n[ux_text text_align=\"center\" class=\"mg0\"]\n\nCopyright © [ux_current_year] Vionis Travel. All rights reserved.\n[/ux_text]\n\n[/col]\n\n[/row]\n\n[/section]', 'Footer', '', 'inherit', 'closed', 'closed', '', '243-revision-v1', '', '', '2026-07-10 22:28:15', '2026-07-10 15:28:15', '', 243, 'https://vionistravel.com/?p=1725', 0, 'revision', '', 0);
