(1798, 7, '2026-07-14 10:20:40', '2026-07-14 03:20:40', '{\n    \"custom_css[flatsome-child]\": {\n        \"value\": \"\\n\\n/* B\\u1ecf uppercase to\\u00e0n b\\u1ed9 menu dropdown */\\n.nav-dropdown a,\\n.nav-dropdown ul a,\\n.nav-dropdown li > a,\\n.nav-dropdown .nav-dropdown-col > a,\\n.nav-dropdown .sub-menu a,\\n.nav-dropdown .nav-column a{\\n    text-transform: none !important;\\n}\\n\\n/*css danh m\\u1ee5c tour*/\\n.vionis-tour-card h3 {\\n\\tfont-size: 30px !important;\\n}\\n\\n.vionis-tour-card h3 {\\n    line-height: 38px !important;\\n}\\n\\n/*css header*/\\n#header .header-nav-main>.menu-item>a{\\n\\tfont-size: 15px !important;\\n}\\n.header-nav-main>li {\\n    margin: 0 10px !important;\\n}\\n\\n.trust h2,\\n.trust h4{\\n\\tcolor: white;\\n}\\n\\n/*css contact form about*/\\n.page-id-59 #wpcf7-f87-p59-o1 .wpcf7-text,\\n.page-id-59 #wpcf7-f87-p59-o1 .wpcf7-email,\\n.page-id-59 #wpcf7-f87-p59-o1 .wpcf7-tel,\\n.page-id-59 #wpcf7-f87-p59-o1 .wpcf7-textarea {\\n    color: var(--primary-color);\\n}\\n\\n/*css menu header*/\\n.nav-left {\\n    justify-content: center;\\n}\\n/*css menu header*/\\n\\n/*css social footer*/\\n.footer-social{\\n    display:flex;\\n    gap:10px;\\n    align-items:center;\\n    flex-wrap:wrap;\\n}\\n\\n.footer-social a{\\n    width:40px;\\n    height:40px;\\n    border-radius:50%;\\n    background:#2b322d;\\n    color:#fff;\\n    display:flex;\\n    align-items:center;\\n    justify-content:center;\\n    text-decoration:none;\\n    transition:all .3s ease;\\n}\\n\\n.footer-social a:hover{\\n    background:#127faf;\\n    transform:translateY(-2px);\\n}\\n\\n.footer-social a i{\\n    font-size:18px;\\n    line-height:1;\\n}\\n\\n.footer-social a img{\\n    width:22px;\\n    height:22px;\\n    object-fit:contain;\\n    display:block;\\n}\\n/*css social footer*/\\n\\n.html_nav_position_text {\\n    margin-right: 0 !important;\\n}\\n\\n/*css 1/6/2026*/\\n.main-title * {\\n    font-size: clamp(1.75rem, 5vw, 3rem); /* 28px -> 48px */\\n    font-weight: bold;\\n}\\n\\n.mobile {\\n    display: none;\\n}\\n\\n@media (max-width: 767px) {\\n    .mobile {\\n        display: block;\\n    }\\n}\\n\\n.gtranslate-custom {\\n    text-align: right;\\n}\\n\\n.lightbox-content {\\n    padding: 30px 30px 10px 30px !important;\\n}\\n\\n/*css 1/6/2026*/\\n\\n/* Giao di\\u1ec7n GTranslate */\\n.gtranslate-custom select {\\n    background-color: #ffffff;\\n    color: #222;\\n    border: 1px solid #ddd;\\n    border-radius: 8px;\\n    padding: 6px 10px;\\n    font-size: 15px;\\n    box-shadow: 0 1px 4px rgba(0,0,0,0.08);\\n    cursor: pointer;\\n    transition: all 0.3s ease;\\n}\\n\\n/* Hover select */\\n.gtranslate-custom select:hover {\\n    border-color: #0073e6;\\n    background-color: #f0f8ff;\\n}\\n\\n/* Link ng\\u00f4n ng\\u1eef */\\n.gtranslate-custom a {\\n    display: inline-flex;\\n    align-items: center;\\n    text-decoration: none;\\n    padding: 6px 10px;\\n    margin: 5px 3px;\\n    background: #f9f9f9;\\n    color: #333;\\n    border: 1px solid #ddd;\\n    border-radius: 6px;\\n    font-size: 14px;\\n    transition: all 0.3s;\\n}\\n\\n/* Icon c\\u1edd qu\\u1ed1c gia trong link */\\n.gtranslate-custom a img {\\n    width: 20px;\\n    height: 14px;\\n    margin-right: 5px;\\n    object-fit: cover;\\n}\\n\\n/* Hover link */\\n.gtranslate-custom a:hover {\\n    background: #0073e6;\\n    color: #fff;\\n    border-color: #0073e6;\\n}\\n\\n/* Responsive Mobile */\\n@media (max-width: 768px) {\\n    .gtranslate-custom {\\n        display: flex;\\n        justify-content: center; /* C\\u0103n gi\\u1eefa */\\n        align-items: center;\\n        flex-wrap: nowrap; /* Kh\\u00f4ng cho xu\\u1ed1ng h\\u00e0ng */\\n        gap: 5px;\\n    }\\n    .gtranslate-custom a {\\n        flex: 0 0 auto;\\n        padding: 4px 8px;\\n        font-size: 13px;\\n    }\\n    .gtranslate-custom a img {\\n        width: 16px; /* Icon nh\\u1ecf h\\u01a1n */\\n        height: 12px;\\n        margin-right: 3px;\\n    }\\n}\\n\\n.has-hover .bg,\\n.has-hover [class*=image-] img {\\n    transition: filter 0.6s ease, opacity 0.6s ease, transform 0.6s ease, box-shadow 0.4s ease;\\n    transform-origin: center center;\\n}\\n\\n/* Khi hover */\\n.has-hover:hover .bg,\\n.has-hover:hover [class*=image-] img {\\n    transform: scale(1.03) rotateZ(0.3deg) translateY(-2px); /* chuy\\u1ec3n \\u0111\\u1ed9ng nh\\u1eb9 l\\u00ean */\\n    filter: brightness(1.2) contrast(1.1) saturate(1.2); /* gi\\u1ea3m \\u0111\\u1ed9 s\\u00e1ng v\\u00e0 b\\u00e3o h\\u00f2a */\\n    box-shadow: 0 0 20px rgba(255, 255, 255, 0.4), \\n                0 0 40px rgba(255, 255, 255, 0.3), \\n                0 0 60px rgba(255, 255, 255, 0.2), \\n                0 5px 10px rgba(0, 0, 0, 0.1); /* b\\u00f3ng \\u0111\\u1ed5 m\\u1ec1m */\\n    opacity: 1;\\n}\\n\\n\\n\\n.box-text a:not(.button),\\n.box-text h4,\\n.box-text h5,\\n.box-text h6 {\\n    line-height: 1.3;\\n    color: rgb(211 27 27);\\n    margin-bottom: .1em;\\n    margin-top: .1em;\\n    transition: color 0.3s ease, transform 0.3s ease;\\n}\\n\\n.box-text a:not(.button):hover,\\n.box-text h4:hover,\\n.box-text h5:hover,\\n.box-text h6:hover {\\n    color: rgb(255, 0, 0);\\n    transform: translateY(-3px);\\n    cursor: pointer;\\n}\\n\\n\\n\\n.home_blog .box-blog-post:hover {\\n    box-shadow: 0 0px 22px #84c8ff;\\n    transform: scale(1.02);\\n    padding: 10px 20px;\\n    text-align: left;\\n}\\n.home_blog .box-blog-post {\\n    box-shadow: 0 0 18px rgba(0, 0, 0, 0.05);\\n    border-radius: 10px; /* Bo g\\u00f3c */\\n    transition: all 0.s ease;\\n}\\n.home_blog .box-blog-post:hover {\\n    box-shadow: 0 0px 5px #84c8ff;\\n    transform: scale(1.02);\\n    padding: 10px 20px;\\n    text-align: left;\\n    border: 1px solid rgba(0, 0, 0, 0.05); /* Gi\\u1eef vi\\u1ec1n khi hover */\\n}\\n\\n\\n.tour-outbound {\\n    padding: 4.18rem var(--section) 8.81rem;\\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\\n    display: flex\\n;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n}\\n\\n.tour-outbound .tour-outbound__title h2 {\\n    color: #fff;\\n    font-size: clamp(1.8rem, 5vw, 3.5rem);\\n    font-style: normal;\\n    font-weight: 700;\\n    line-height: 1.2;\\n    text-transform: uppercase;\\n}\\n\\n.home-introduce .home-introduce__title h1 {\\n    margin-bottom: 1.06rem;\\n}\\n\\n.phongvt-title-main h2,\\n.phongvt-title-main h1,\\n.phongvt-title-main h3,\\n.phongvt-title-main-p p {\\n    object-position: 50% 50%;\\n    color: var(--Color, #06346c);\\n    font-size: 3.5rem;\\n    font-style: normal;\\n    font-weight: 700;\\n    line-height: normal;\\n    text-transform: uppercase;\\n}\\n\\n/* Tablet */\\n@media (max-width: 991px) {\\n    .phongvt-title-main h2,\\n    .phongvt-title-main h1,\\n    .phongvt-title-main h3,\\n    .phongvt-title-main-p p {\\n        font-size: 2.5rem;\\n    }\\n}\\n\\n/* Mobile */\\n@media (max-width: 767px) {\\n    .phongvt-title-main h2,\\n    .phongvt-title-main h1,\\n    .phongvt-title-main h3,\\n    .phongvt-title-main-p p {\\n        font-size: 1.8rem;\\n        line-height: 1.3;\\n    }\\n}\\n\\n\\n\\n.tour-outbound {\\n    padding: 4.18rem var(--section) 8.81rem;\\n    background: var(--Linear, linear-gradient(90deg, var(--Color, #023F88) 0%, var(--Color-2, #0071BB) 100%));\\n    display: flex\\n;\\n    flex-wrap: wrap;\\n    justify-content: space-between;\\n}\\n\\n.fix-section {\\n    border-radius: 2.75rem 2.75rem 0rem 0rem;\\n    background: linear-gradient(180deg, #01549D 0%, var(--Color-2, #0071BB) 60.5%);\\n    padding: 4.44rem var(--section) 16.45rem;\\n    overflow: hidden;\\n}\\n\\n\\n.appointment .item label {\\n    font-size: 14px;\\n    font-weight: 500;\\n    position: absolute;\\n    z-index: 1;\\n    background: #fff;\\n    left: 10px;\\n\\n    padding: 0 10px;\\n    display: inline-block;\\n    width: auto;\\n    border-radius: 8px;\\n    color: #333;\\n}\\n.appointment {\\n    background: #fff;\\n    position: relative;\\n    z-index: 1;\\n}\\n\\n\\n#header .header-nav-main>.menu-item>a {\\n    color: #404040;\\n    font-size: 1.1rem;\\n    font-style: normal;\\n\\ttransition: color 0.3s ease;\\n    font-weight: 600;\\n    line-height: 1.35rem;\\n    padding: var(--30) 0;\\n}\\n#header .header-nav-main > .menu-item.current-menu-item > a {\\n    color: #023f88; /* M\\u00e0u xanh d\\u01b0\\u01a1ng */\\n}\\n#header .header-nav-main > .menu-item > a:hover {\\n    color: #023f88; /* M\\u00e0u xanh d\\u01b0\\u01a1ng */\\n}\\n\\n\\n.phongvt-hieu-ung-toa-hinh {\\n    display: block;\\n    position: relative;\\n    overflow: hidden\\n}\\n\\n.phongvt-hieu-ung-toa-hinh:before {\\n    position: absolute;\\n    top: 50%;\\n    left: 50%;\\n    z-index: 2;\\n    display: block;\\n    content: \'\';\\n    width: 0;\\n    height: 0;\\n    background: rgba(255,255,255,0.2);\\n    border-radius: 100%;\\n    opacity: 0;\\n    -webkit-transform: translate(-50%, -50%);\\n    -ms-transform: translate(-50%, -50%);\\n    -o-transform: translate(-50%, -50%);\\n    transform: translate(-50%, -50%)\\n}\\n\\n@media (min-width: 1025px) {\\n    .phongvt-hieu-ung-toa-hinh:hover:before {\\n        -webkit-animation:circle 0.75s;\\n        -ms-animation: circle 0.75s;\\n        -o-animation: circle 0.75s;\\n        animation: circle 0.75s\\n    }\\n}\\n\\n@-ms-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-o-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@-webkit-keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\\n\\n@keyframes circle {\\n    0% {\\n        opacity: 1\\n    }\\n\\n    40% {\\n        opacity: 1\\n    }\\n\\n    100% {\\n        width: 200%;\\n        height: 200%;\\n        opacity: 0\\n    }\\n}\",\n        \"type\": \"custom_css\",\n        \"user_id\": 7,\n        \"date_modified_gmt\": \"2026-07-14 03:20:40\"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'bb9392d7-96ab-4496-acd3-78b834ac1260', '', '', '2026-07-14 10:20:40', '2026-07-14 03:20:40', '', 0, 'https://vionistravel.com/?p=1798', 0, 'customize_changeset', '', 0),
(1799, 7, '2026-07-14 10:20:54', '2026-07-14 03:20:54', '[section bg=\"1753\" bg_size=\"original\" bg_pos=\"37% 63%\" dark=\"true\" padding=\"0px\" height=\"70vh\" height__sm=\"100vh\" height__md=\"60vh\" video_mp4=\"/wp-content/uploads/2026/07/VIONIS-VIETNAM-TRAVEL-NEW.mp4\" video_visibility=\"visible\"]\n\n[row]\n\n[col span__sm=\"12\" align=\"center\"]\n\n[ux_text font_size=\"3\" font_size__sm=\"2\" text_align=\"center\" class=\"extra mg0\"]\n\n<strong>Vionis Travel – Your trusted travel partner for every journey. </strong>\n[/ux_text]\n[ux_text font_size=\"2.5\" font_size__sm=\"1\"]\n\nYour Perfect Trip Starts Here\n[/ux_text]\n[row_inner]\n\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[search style=\"flat\" size=\"xlarge\" visibility=\"hidden\"]\n\n[ux_html]\n\n[tour_search_filter]\n[/ux_html]\n\n[/col_inner]\n[col_inner span=\"3\" span__sm=\"12\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n\n[/row]\n\n[/section]\n[section bg_color=\"rgba(18, 127, 175, 0.064)\" padding__sm=\"20px\"]\n\n[row]\n\n[col span__sm=\"12\" margin=\"30px 0px 0px 0px\" margin__sm=\"0px 0px 0px 0px\"]\n\n[ux_html visibility=\"hidden\"]\n\n<style>\n/*=========================\n    FEATURES\n=========================*/\n.vionis-features{\n    display:grid;\n    grid-template-columns:repeat(4,1fr);\n    background:#fff;\n    border-radius:18px;\n    overflow:hidden;\n    box-shadow:0 10px 35px rgba(0,0,0,.08);\n}\n\n.vionis-features .feature-item{\n    padding:34px 24px;\n    text-align:center;\n    border-right:1px solid #ececec;\n    transition:.3s;\n}\n\n.vionis-features .feature-item:last-child{\n    border-right:none;\n}\n\n.vionis-features .feature-item:hover{\n    background:#fafafa;\n}\n\n.vionis-features .feature-icon{\n    width:52px;\n    height:52px;\n    margin:0 auto 18px;\n    color:#d6a31b;\n}\n\n.vionis-features .feature-icon svg,\n.vionis-features .feature-icon img{\n    width:100%;\n    height:100%;\n    display:block;\n    object-fit:contain;\n}\n\n.vionis-features h4{\n    margin:0;\n    font-size:20px;\n    line-height:1.45;\n    font-weight:700;\n    color:#1d1d1d;\n}\n\n/* Tablet */\n\n@media (max-width:849px){\n\n    .vionis-features{\n        grid-template-columns:repeat(2,1fr);\n    }\n\n    .vionis-features .feature-item:nth-child(2){\n        border-right:none;\n    }\n\n    .vionis-features .feature-item:nth-child(-n+2){\n        border-bottom:1px solid #ececec;\n    }\n\n}\n\n/* Mobile */\n\n@media (max-width:549px){\n\n    .vionis-features{\n        grid-template-columns:1fr;\n    }\n\n    .vionis-features .feature-item{\n        border-right:none;\n        border-bottom:1px solid #ececec;\n        padding:26px 20px;\n    }\n\n    .vionis-features .feature-item:last-child{\n        border-bottom:none;\n    }\n\n    .vionis-features h4{\n        font-size:17px;\n    }\n\n    .vionis-features .feature-icon{\n        width:44px;\n        height:44px;\n    }\n\n}\n</style>\n\n<div class=\"vionis-features\">\n\n    <!-- Feature 1 -->\n    <div class=\"feature-item\">\n        <div class=\"feature-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\">\n                <path d=\"M12 21s7-5.5 7-11a7 7 0 10-14 0c0 5.5 7 11 7 11z\"/>\n                <circle cx=\"12\" cy=\"10\" r=\"2.5\"/>\n            </svg>\n        </div>\n        <h4>Handpicked Tours<br>& Activities</h4>\n    </div>\n\n    <!-- Feature 2 -->\n    <div class=\"feature-item\">\n        <div class=\"feature-icon\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\">\n                <path d=\"M12 3l7 3v5c0 5-3.5 8-7 10-3.5-2-7-5-7-10V6l7-3z\"/>\n                <path d=\"M9 12l2 2 4-4\"/>\n            </svg>\n        </div>\n        <h4>Easy & Secure<br>Booking</h4>\n    </div>\n\n    <!-- Feature 3 -->\n    <div class=\"feature-item\">\n        <div class=\"feature-icon\">\n            <img src=\"https://v